        Light = @{
            WindowBg      = "#FFFFFF"
            WindowBorder  = "#D1D4D7"
            TitleBg       = "#F2F3F5"
            TitleFg       = "#2E3338"
            TextPrimary   = "#2E3338"
            TextMuted     = "#5C6067"
            CardBg        = "#F2F3F5"
            CardBorder    = "#D1D4D7"
            CardCheckedBg = "#E0E3FA"
            BadgeBorder   = "#949BA4"
            LogBg         = "#F8F9FA"
            LogBorder     = "#D1D4D7"
            LogFg         = "#2E3338"
