    $TitleBar.Add_MouseLeftButtonDown({ $window.DragMove() })
    $btnMin.Add_Click({ $window.WindowState = 'Minimized' })
    $btnClose.Add_Click({ $window.Close() })
    $window.Add_Closed({
        if ($Host.Name -notlike "*ISE*" -and $Host.Name -notlike "*Visual Studio*") {
            [System.Environment]::Exit(0)
        }
    })

    $window.Add_Loaded({
        $window.WindowState = 'Normal'
        $window.Topmost = $true
        $window.Activate()
        $window.Focus()
        try {
            $helper = New-Object System.Windows.Interop.WindowInteropHelper($window)
            if ($helper.Handle -ne [System.IntPtr]::Zero) {
                [WinUtil.WinUtil]::SetForegroundWindow($helper.Handle)
            }
        } catch {}
    })

    $global:BrushConverter = New-Object System.Windows.Media.BrushConverter
    $global:GeomSun  = [System.Windows.Media.Geometry]::Parse("M12,8 A4,4 0 1,0 12,16 A4,4 0 1,0 12,8 Z M12,2 L12,4 M12,20 L12,22 M2,12 L4,12 M20,12 L22,12 M4.93,4.93 L6.34,6.34 M17.66,17.66 L19.07,19.07 M4.93,19.07 L6.34,17.66 M17.66,6.34 L19.07,4.93")
    $global:GeomMoon = [System.Windows.Media.Geometry]::Parse("M12,3 A6,6 0 0,0 21,12 A9,9 0 1,1 12,3 Z")
    function script:Get-Brush($hex) {
        return $global:BrushConverter.ConvertFromString($hex)
    }
    function Get-Brush($hex) {
        return script:Get-Brush $hex
    }

    function Get-IconBmp($paths, $b64) {
        foreach ($p in $paths) {
            if ($p -and [System.IO.File]::Exists($p)) {
                try {
                    $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
                    $bmp.BeginInit()
                    $bmp.UriSource = New-Object System.Uri($p, [System.UriKind]::Absolute)
                    $bmp.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                    $bmp.EndInit()
                    $bmp.Freeze()
                    return $bmp
                } catch {}
            }
        }
        if ($b64) {
            try {
                $bytes = [System.Convert]::FromBase64String($b64)
                $ms = New-Object System.IO.MemoryStream(,$bytes)
                $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
                $bmp.BeginInit()
                $bmp.StreamSource = $ms
                $bmp.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $bmp.EndInit()
                $bmp.Freeze()
                return $bmp
            } catch {}
        }
        return $null
    }

    $ctxDir = $null
    if ($PSScriptRoot) { $ctxDir = $PSScriptRoot }
    elseif ($MyInvocation.MyCommand.Path) {
        try { $ctxDir = [System.IO.Path]::GetDirectoryName($MyInvocation.MyCommand.Path) } catch {}
    }
    if (-not $ctxDir) {
        try {
            $cur = (Get-Location).Path
            if ([System.IO.File]::Exists([System.IO.Path]::Combine($cur, "dist\patcher.js"))) { $ctxDir = $cur }
        } catch {}
    }

    $pathsStable = @([System.IO.Path]::Combine((Get-Location).Path, "discord.png"))
    if ($ctxDir) { $pathsStable += [System.IO.Path]::Combine($ctxDir, "discord.png") }

    $pathsPTB = @([System.IO.Path]::Combine((Get-Location).Path, "discord-ptb.png"))
    if ($ctxDir) { $pathsPTB += [System.IO.Path]::Combine($ctxDir, "discord-ptb.png") }

    $pathsCanary = @([System.IO.Path]::Combine((Get-Location).Path, "discord-canary.png"))
    if ($ctxDir) { $pathsCanary += [System.IO.Path]::Combine($ctxDir, "discord-canary.png") }

    $imgStable.Source = Get-IconBmp $pathsStable $b64Stable
    $imgPTB.Source    = Get-IconBmp $pathsPTB $b64PTB
    $imgCanary.Source = Get-IconBmp $pathsCanary $b64Canary

    function Update-Theme {
        $thm = $global:Themes[$global:CurrentTheme]
        foreach ($k in $thm.Keys) {
            $window.Resources[$k] = Get-Brush $thm[$k]
        }
        $MainBorder.Background       = Get-Brush $thm.WindowBg
        $MainBorder.BorderBrush      = Get-Brush $thm.WindowBorder
        $TitleBar.Background         = Get-Brush $thm.TitleBg
        $txtTitle.Foreground         = Get-Brush $thm.TitleFg
        $btnTheme.Foreground         = Get-Brush $thm.BtnWinFg
        $pathThemeIcon.Stroke        = Get-Brush $thm.BtnWinFg
        $btnLang.Foreground          = Get-Brush $thm.BtnWinFg
        $btnMin.Foreground           = Get-Brush $thm.BtnWinFg
        $btnClose.Foreground         = Get-Brush $thm.BtnWinFg
        $lblSelectTargets.Foreground = Get-Brush $thm.TextMuted
        $lblStatus.Foreground        = Get-Brush $thm.TextMuted
        $lblLog.Foreground           = Get-Brush $thm.TextMuted
        $pb.Background               = Get-Brush $thm.PbTrack
        $BorderLog.Background        = Get-Brush $thm.LogBg
        $BorderLog.BorderBrush       = Get-Brush $thm.LogBorder
        $txtLog.Foreground           = Get-Brush $thm.LogFg
        $txtStable.Foreground        = Get-Brush $thm.TextPrimary
        $txtPTB.Foreground           = Get-Brush $thm.TextPrimary
        $txtCanary.Foreground        = Get-Brush $thm.TextPrimary

        Update-ThemeBtn
    }

    function Update-ThemeBtn {
        $d = $global:i18n[$global:CurrentLang]
        if ($global:CurrentTheme -eq "Dark") {
            $pathThemeIcon.Data = $global:GeomMoon
            $btnTheme.ToolTip   = $d.ThemeDark
        } else {
            $pathThemeIcon.Data = $global:GeomSun
            $btnTheme.ToolTip   = $d.ThemeLight
        }
    }

    function Update-Language {
        $d = $global:i18n[$global:CurrentLang]
        $txtTitle.Text            = $d.Title
        $btnLang.Content          = $d.LangBtn
        $lblSelectTargets.Text    = $d.SelectTargets
        $txtStable.Text           = $d.Discord
        $txtPTB.Text              = $d.DiscordPTB
        $txtCanary.Text           = $d.DiscordCanary
        $btnInstall.Content       = $d.BtnInstall
        $btnUninstall.Content     = $d.BtnUninstall
        $lblStatus.Text           = $d.Ready
        $lblLog.Text              = $d.LogHeader
        Update-ThemeBtn
    }

    $btnTheme.Add_Click({
        if ($global:CurrentTheme -eq "Dark") { $global:CurrentTheme = "Light" } else { $global:CurrentTheme = "Dark" }
        Update-Theme
    })

    $btnLang.Add_Click({
        if ($global:CurrentLang -eq "EN") { $global:CurrentLang = "TH" } else { $global:CurrentLang = "EN" }
        Update-Language
    })

    function Get-DiscordPaths {
        $res = @{ "Discord" = @(); "DiscordPTB" = @(); "DiscordCanary" = @() }
        $list = @(
            @{ B = "Discord";       P = "$env:LOCALAPPDATA\Discord" },
            @{ B = "DiscordPTB";    P = "$env:LOCALAPPDATA\DiscordPTB" },
            @{ B = "DiscordCanary"; P = "$env:LOCALAPPDATA\DiscordCanary" }
        )
        foreach ($i in $list) {
            if ([System.IO.Directory]::Exists($i.P)) { $res[$i.B] += $i.P }
        }
        if ([System.IO.Directory]::Exists("C:\ProgramData")) {
            foreach ($k in @("Discord", "DiscordPTB", "DiscordCanary")) {
                try {
                    $m = [System.IO.Directory]::GetDirectories("C:\ProgramData", "*$k*", [System.IO.SearchOption]::AllDirectories)
                    if ($m) {
                        foreach ($x in $m) {
                            if ($x -and -not ($res[$k] -contains $x)) { $res[$k] += $x }
                        }
                    }
                } catch {}
            }
        }
        return $res
    }

    $detected = Get-DiscordPaths
    if ($detected["Discord"].Count -gt 0) { $chkStable.IsChecked = $true }
    if ($detected["DiscordPTB"].Count -gt 0) { $chkPTB.IsChecked = $true }
    if ($detected["DiscordCanary"].Count -gt 0) { $chkCanary.IsChecked = $true }
    if (-not $chkStable.IsChecked -and -not $chkPTB.IsChecked -and -not $chkCanary.IsChecked) {
        $chkStable.IsChecked = $true
    }

    function script:Set-State($en) {
        $script:btnInstall.IsEnabled   = $en
        $script:btnUninstall.IsEnabled = $en
        $script:chkStable.IsEnabled    = $en
        $script:chkPTB.IsEnabled       = $en
        $script:chkCanary.IsEnabled    = $en
        $script:btnTheme.IsEnabled     = $en
        $script:btnLang.IsEnabled      = $en
    }
    function Set-State($en) {
        script:Set-State $en
    }

    function Run-Action($action) {
        $selected = @()
        if ($script:chkStable.IsChecked) { $selected += "Discord" }
        if ($script:chkPTB.IsChecked) { $selected += "DiscordPTB" }
        if ($script:chkCanary.IsChecked) { $selected += "DiscordCanary" }

        if ($selected.Count -eq 0) {
            $script:lblStatus.Text = $global:i18n[$global:CurrentLang].SelectOne
            $script:lblStatus.Foreground = script:Get-Brush "#F23F43"
            return
        }

        script:Set-State $false
        $script:pb.Value = 0
        $script:pb.IsIndeterminate = $true
        $script:lblStatus.Text = $global:i18n[$global:CurrentLang].Working
        $script:lblStatus.Foreground = script:Get-Brush $global:Themes[$global:CurrentTheme].TextMuted

        $d = $global:i18n[$global:CurrentLang]
        $startMsg = if ($action -eq "Install") { $d.LogStartingInstall } else { $d.LogStartingUninstall }
        $txtLog.AppendText("[$([DateTime]::Now.ToString('HH:mm:ss'))] $startMsg`r`n")
        $txtLog.ScrollToEnd()

        $script:txtLog    = $txtLog
        $script:lblStatus = $lblStatus
        $script:pb        = $pb

        $ctxDir = $null
        if ($PSScriptRoot) { $ctxDir = $PSScriptRoot }
        elseif ($MyInvocation.MyCommand.Path) {
            try { $ctxDir = [System.IO.Path]::GetDirectoryName($MyInvocation.MyCommand.Path) } catch {}
        }
        if (-not $ctxDir) {
            try {
                $cur = (Get-Location).Path
                if ([System.IO.File]::Exists([System.IO.Path]::Combine($cur, "dist\patcher.js"))) { $ctxDir = $cur }
            } catch {}
        }

        $sync = [hashtable]::Synchronized(@{
            Action   = $action
            Targets  = $selected
            Paths    = (Get-DiscordPaths)
            LocalDir = $ctxDir
            Lang     = $global:CurrentLang
            I18n     = $global:i18n[$global:CurrentLang]
            DistUrl  = "https://raw.githubusercontent.com/phwyverysad/discord-fake-mute-deafen/main/dist.zip"
            RepoUrl  = "https://github.com/phwyverysad/discord-fake-mute-deafen/archive/refs/heads/main.zip"
            CliUrl   = "https://github.com/Vencord/Installer/releases/latest/download/VencordInstallerCli.exe"
            Logs     = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
            Done     = $false
            Error    = $null
        })

        $worker = {
            param($sync)

            function global:Add-Log($msg) {
                $ts = [DateTime]::Now.ToString("HH:mm:ss")
                $null = $sync.Logs.Add("[$ts] $msg")
            }
            function Add-Log($msg) { global:Add-Log $msg }

            function global:Invoke-Cli($cliExe, $cliArgs) {
                try {
                    try {
                        $oldProcs = [System.Diagnostics.Process]::GetProcessesByName("VencordInstallerCli")
                        if ($oldProcs) {
                            foreach ($p in $oldProcs) {
                                try { $p.Kill() } catch {}
                            }
                        }
                    } catch {}

                    $psi = New-Object System.Diagnostics.ProcessStartInfo
                    $psi.FileName = $cliExe
                    $psi.Arguments = $cliArgs
                    $psi.UseShellExecute = $false
                    $psi.RedirectStandardOutput = $true
                    $psi.RedirectStandardError = $true
                    $psi.RedirectStandardInput = $true
                    $psi.CreateNoWindow = $true

                    $proc = [System.Diagnostics.Process]::Start($psi)
                    if ($proc) {
                        $proc.StandardInput.Close()
                        $outTask = $proc.StandardOutput.ReadToEndAsync()
                        $errTask = $proc.StandardError.ReadToEndAsync()

                        if ($proc.WaitForExit(15000)) {
                            $outStr = $outTask.Result
                            $errStr = $errTask.Result
                            $all = @()
                            if ($errStr) { $all += ($errStr -split "`r?`n") }
                            if ($outStr) { $all += ($outStr -split "`r?`n") }
                            foreach ($l in $all) {
                                $c = $l.Trim()
                                if ($c -and -not ($c -like "*Failed to fetch https://api.github.com*") -and -not ($c -like "*Press Enter to exit*")) {
                                    global:Add-Log $c
                                }
                            }
                        } else {
                            try { $proc.Kill() } catch {}
                            global:Add-Log "Process timed out after 15 seconds."
                        }
                    }
                } catch {
                    global:Add-Log ("CLI error: " + $_.Exception.Message)
                }
            }
            function Invoke-Cli($cliExe, $cliArgs) { global:Invoke-Cli $cliExe $cliArgs }

            try {
                [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]3072 -bor [System.Net.SecurityProtocolType]768 -bor [System.Net.SecurityProtocolType]192

                $vDir = [System.IO.Path]::Combine($env:APPDATA, "Vencord")
                $tDist = [System.IO.Path]::Combine($vDir, "dist")
                $sFile = [System.IO.Path]::Combine($vDir, "settings\settings.json")
                $msg = $sync.I18n

                $src = $null
                $cli = $null
                $tmp = $null
                $cacheDir = [System.IO.Path]::Combine($env:LOCALAPPDATA, "FakeMuteDeafen\dist")

                $cliCandidates = @()
                if ($sync.LocalDir) { $cliCandidates += [System.IO.Path]::Combine($sync.LocalDir, "VencordInstallerCli.exe") }
                $cliCandidates += [System.IO.Path]::Combine($env:TEMP, "VencordInstallerCli.exe")
                $cliCandidates += [System.IO.Path]::Combine($env:APPDATA, "Vencord\dist\Installer\VencordInstallerCli.exe")
                $cliCandidates += [System.IO.Path]::Combine($env:LOCALAPPDATA, "FakeMuteDeafen\VencordInstallerCli.exe")

                foreach ($c in $cliCandidates) {
                    if ([System.IO.File]::Exists($c)) {
                        try {
                            $fi = New-Object System.IO.FileInfo($c)
                            if ($fi.Length -gt 1000000) {
                                $cli = $c
                                break
                            }
                        } catch {}
                    }
                }

                if ($sync.LocalDir) {
                    $lDist = [System.IO.Path]::Combine($sync.LocalDir, "dist")
                    if ([System.IO.Directory]::Exists($lDist) -and [System.IO.File]::Exists([System.IO.Path]::Combine($lDist, "patcher.js"))) {
                        $src = $lDist
                    }
                }
                if (-not $src -and [System.IO.File]::Exists([System.IO.Path]::Combine($cacheDir, "patcher.js"))) {
                    $src = $cacheDir
                }

                $targetLocations = @()
                foreach ($target in $sync.Targets) {
                    $paths = $sync.Paths[$target]
                    if ($paths -and $paths.Count -gt 0) {
                        foreach ($p in $paths) {
                            if ([System.IO.Directory]::Exists($p) -and -not ($targetLocations -contains $p)) {
                                $targetLocations += $p
                            }
                        }
                    }
                }

                if ($sync.Action -eq "Uninstall") {
                    Add-Log $msg.LogStep1CloseUn
                    $procs = [System.Diagnostics.Process]::GetProcesses()
                    $closedCount = 0
                    foreach ($p in $procs) {
                        try {
                            $pName = $p.ProcessName
                            if ($pName -like "*Discord*" -and $pName -notlike "*Helper*") {
                                $p.Kill()
                                $closedCount++
                            }
                        } catch {}
                    }
                    if ($closedCount -gt 0) {
                        [System.Threading.Thread]::Sleep(1000)
                        Add-Log $msg.LogDiscordClosed
                    } else {
                        Add-Log $msg.LogDiscordNotRunning
                    }

                    if (-not $cli) {
                        $tempCli = [System.IO.Path]::Combine($env:TEMP, "VencordInstallerCli.exe")
                        if (-not [System.IO.File]::Exists($tempCli)) {
                            $wc = New-Object System.Net.WebClient
                            $wc.Headers.Add("User-Agent", "Mozilla/5.0")
                            $wc.DownloadFile($sync.CliUrl, $tempCli)
                        }
                        $cli = $tempCli
                    }

                    Add-Log $msg.LogStep2Unpatch
                    $unpatchedCount = 0
                    if ($targetLocations -and $targetLocations.Count -gt 0) {
                        foreach ($loc in $targetLocations) {
                            Add-Log ([string]::Format($msg.LogDetectedDiscord, $loc))
                            Invoke-Cli $cli ("-uninstall -location `"" + $loc + "`"")
                            $unpatchedCount++
                        }
                    }
                    if ($unpatchedCount -eq 0) {
                        Invoke-Cli $cli "-uninstall -branch auto"
                    }
                    Add-Log $msg.LogUnpatchSuccess

                    Add-Log $msg.LogStep3Disable
                    if ([System.IO.File]::Exists($sFile)) {
                        try {
                            $raw = [System.IO.File]::ReadAllText($sFile, [System.Text.Encoding]::UTF8)
                            $c = $raw | ConvertFrom-Json -AsHashtable
                            if ($c.ContainsKey("plugins") -and $c["plugins"].ContainsKey("FakeMuteDeafen")) {
                                $c["plugins"]["FakeMuteDeafen"]["enabled"] = $false
                                $utf8 = New-Object System.Text.UTF8Encoding($false)
                                [System.IO.File]::WriteAllText($sFile, ($c | ConvertTo-Json -Depth 10), $utf8)
                            }
                        } catch {}
                    }

                    Add-Log $msg.LogStep4LaunchUn
                    $launched = $false
                    if ($targetLocations) {
                        foreach ($loc in $targetLocations) {
                            $upd = [System.IO.Path]::Combine($loc, "Update.exe")
                            $exeName = [System.IO.Path]::GetFileName($loc) + ".exe"
                            if ([System.IO.File]::Exists($upd)) {
                                try {
                                    [System.Diagnostics.Process]::Start($upd, "--processStart " + $exeName) | Out-Null
                                    $launched = $true
                                    break
                                } catch {}
                            }
                        }
                    }
                    if ($launched) {
                        Add-Log $msg.LogDiscordLaunched
                    }

                    Add-Log $msg.LogUninstallSuccess
                    $sync.Done = $true
                    return
                }

                Add-Log $msg.LogStep1Close
                $procs = [System.Diagnostics.Process]::GetProcesses()
                $closedCount = 0
                foreach ($p in $procs) {
                    try {
                        $pName = $p.ProcessName
                        if ($pName -like "*Discord*" -and $pName -notlike "*Helper*") {
                            $p.Kill()
                            $closedCount++
                        }
                    } catch {}
                }
                if ($closedCount -gt 0) {
                    [System.Threading.Thread]::Sleep(1000)
                    Add-Log $msg.LogDiscordClosed
                } else {
                    Add-Log $msg.LogDiscordNotRunning
                }

                Add-Log $msg.LogStep2Check
                if (-not $src) {
                    if (-not [System.IO.Directory]::Exists($cacheDir)) {
                        [System.IO.Directory]::CreateDirectory($cacheDir) | Out-Null
                    } else {
                        try { [System.IO.Directory]::Delete($cacheDir, $true) } catch {}
                        [System.IO.Directory]::CreateDirectory($cacheDir) | Out-Null
                    }
                    $distZip = [System.IO.Path]::Combine($env:TEMP, "FMD_dist.zip")
                    $wc = New-Object System.Net.WebClient
                    $wc.Headers.Add("User-Agent", "Mozilla/5.0")
                    $dlOk = $false
                    try {
                        $wc.DownloadFile($sync.DistUrl, $distZip)
                        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
                        [System.IO.Compression.ZipFile]::ExtractToDirectory($distZip, $cacheDir)
                        if ([System.IO.File]::Exists($distZip)) {
                            [System.IO.File]::Delete($distZip)
                        }
                        if ([System.IO.File]::Exists([System.IO.Path]::Combine($cacheDir, "patcher.js"))) {
                            $src = $cacheDir
                            $dlOk = $true
                        }
                    } catch {}

                    if (-not $dlOk) {
                        $tmp = [System.IO.Path]::Combine($env:TEMP, ("FMD_" + (Get-Random)))
                        [System.IO.Directory]::CreateDirectory($tmp) | Out-Null
                        $zipFb = [System.IO.Path]::Combine($tmp, "package.zip")
                        $wc.DownloadFile($sync.RepoUrl, $zipFb)
                        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
                        [System.IO.Compression.ZipFile]::ExtractToDirectory($zipFb, $tmp)
                        $subDirs = [System.IO.Directory]::GetDirectories($tmp, "*fake-mute-deafen*")
                        $ext = if ($subDirs -and $subDirs.Length -gt 0) { $subDirs[0] } else { $tmp }
                        $src = [System.IO.Path]::Combine($ext, "dist")
                        if (-not $cli) {
                            $candidateCli = [System.IO.Path]::Combine($ext, "VencordInstallerCli.exe")
                            if ([System.IO.File]::Exists($candidateCli)) { $cli = $candidateCli }
                        }
                    }
                }

                if (-not $cli) {
                    $tempCli = [System.IO.Path]::Combine($env:TEMP, "VencordInstallerCli.exe")
                    if (-not [System.IO.File]::Exists($tempCli)) {
                        $wc = New-Object System.Net.WebClient
                        $wc.Headers.Add("User-Agent", "Mozilla/5.0")
                        $wc.DownloadFile($sync.CliUrl, $tempCli)
                    }
                    $cli = $tempCli
                }
                Add-Log $msg.LogPackageVerified

                Add-Log $msg.LogStep3Patch
                $patchedCount = 0
                if ($targetLocations -and $targetLocations.Count -gt 0) {
                    foreach ($loc in $targetLocations) {
                        Add-Log ([string]::Format($msg.LogDetectedDiscord, $loc))
                        Invoke-Cli $cli ("-install -location `"" + $loc + "`"")
                        $patchedCount++
                    }
                }
                if ($patchedCount -eq 0) {
                    Add-Log $msg.LogAutoBranch
                    Invoke-Cli $cli "-install -branch auto"
                }
                Add-Log $msg.LogPatchSuccess

                Add-Log $msg.LogStep4Copy
                if (-not [System.IO.Directory]::Exists($tDist)) {
                    [System.IO.Directory]::CreateDirectory($tDist) | Out-Null
                }
                foreach ($file in [System.IO.Directory]::GetFiles($src, "*", [System.IO.SearchOption]::AllDirectories)) {
                    $rel = $file.Substring($src.Length).TrimStart("\", "/")
                    $destFile = [System.IO.Path]::Combine($tDist, $rel)
                    $destDir = [System.IO.Path]::GetDirectoryName($destFile)
                    if (-not [System.IO.Directory]::Exists($destDir)) {
                        [System.IO.Directory]::CreateDirectory($destDir) | Out-Null
                    }
                    [System.IO.File]::Copy($file, $destFile, $true)
                }

                $targetThemesDir = [System.IO.Path]::Combine($vDir, "themes")
                if (-not [System.IO.Directory]::Exists($targetThemesDir)) {
                    [System.IO.Directory]::CreateDirectory($targetThemesDir) | Out-Null
                }
                $themeSources = @()
                if ($sync.LocalDir) { $themeSources += [System.IO.Path]::Combine($sync.LocalDir, "midnight.theme.css") }
                $themeSources += [System.IO.Path]::Combine((Get-Location).Path, "midnight.theme.css")
                foreach ($ts in $themeSources) {
                    if ([System.IO.File]::Exists($ts)) {
                        [System.IO.File]::Copy($ts, [System.IO.Path]::Combine($targetThemesDir, "midnight.theme.css"), $true)
                        Add-Log $msg.LogThemeInstalled
                        break
                    }
                }

                $sDir = [System.IO.Path]::Combine($vDir, "settings")
                if (-not [System.IO.Directory]::Exists($sDir)) {
                    [System.IO.Directory]::CreateDirectory($sDir) | Out-Null
                }
                $c = @{}
                if ([System.IO.File]::Exists($sFile)) {
                    try {
                        $raw = [System.IO.File]::ReadAllText($sFile, [System.Text.Encoding]::UTF8)
                        $c = $raw | ConvertFrom-Json -AsHashtable
                    } catch { $c = @{} }
                }
                if (-not $c) { $c = @{} }
                $c["autoUpdate"] = $false
                $c["autoUpdateNotification"] = $false
                if (-not $c.ContainsKey("plugins")) { $c["plugins"] = @{} }
                if (-not $c["plugins"].ContainsKey("FakeMuteDeafen")) { $c["plugins"]["FakeMuteDeafen"] = @{} }
                $c["plugins"]["FakeMuteDeafen"]["enabled"] = $true

                $utf8 = New-Object System.Text.UTF8Encoding($false)
                [System.IO.File]::WriteAllText($sFile, ($c | ConvertTo-Json -Depth 10), $utf8)
                Add-Log $msg.LogSettingsUpdated

                if ($tmp -and [System.IO.Directory]::Exists($tmp)) {
                    try { [System.IO.Directory]::Delete($tmp, $true) } catch {}
                }

                Add-Log $msg.LogStep5Launch
                $launched = $false
                if ($targetLocations) {
                    foreach ($loc in $targetLocations) {
                        $upd = [System.IO.Path]::Combine($loc, "Update.exe")
                        $exeName = [System.IO.Path]::GetFileName($loc) + ".exe"
                        if ([System.IO.File]::Exists($upd)) {
                            try {
                                [System.Diagnostics.Process]::Start($upd, "--processStart " + $exeName) | Out-Null
                                $launched = $true
                                break
                            } catch {}
                        }
                    }
                }
                if ($launched) {
                    Add-Log $msg.LogDiscordLaunched
                }

                Add-Log $msg.LogInstallSuccess
                $sync.Done = $true
            } catch {
                $sync.Error = $_.Exception.Message
                global:Add-Log ([string]::Format($sync.I18n.LogError, $sync.Error))
                $sync.Done = $true
            }
        }

        $script:sync = $sync
        $iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
        $script:rs = [RunspaceFactory]::CreateRunspace($iss)
        $script:rs.ApartmentState = [System.Threading.ApartmentState]::MTA
        $script:rs.Open()

        $script:ps = [PowerShell]::Create()
        $script:ps.Runspace = $script:rs
        $null = $script:ps.AddCommand("Invoke-Command").AddParameter("ScriptBlock", $worker).AddParameter("ArgumentList", @($script:sync))
        $script:h = $script:ps.BeginInvoke()

        $script:timer = New-Object System.Windows.Threading.DispatcherTimer([System.Windows.Threading.DispatcherPriority]::Normal, $window.Dispatcher)
        $script:timer.Interval = [TimeSpan]::FromMilliseconds(50)
        $script:timer.Add_Tick({
            while ($script:sync.Logs.Count -gt 0) {
                $entry = $script:sync.Logs[0]
                $script:sync.Logs.RemoveAt(0)
                $script:txtLog.AppendText($entry + "`r`n")
                $script:txtLog.ScrollToEnd()
            }
            if ($script:h.IsCompleted -or $script:sync.Done) {
                while ($script:sync.Logs.Count -gt 0) {
                    $entry = $script:sync.Logs[0]
                    $script:sync.Logs.RemoveAt(0)
                    $script:txtLog.AppendText($entry + "`r`n")
                    $script:txtLog.ScrollToEnd()
                }
                $script:timer.Stop()
                $script:pb.IsIndeterminate = $false
                $script:pb.Value = 100

                $d = $global:i18n[$global:CurrentLang]
                if ($script:sync.Error) {
                    $script:lblStatus.Text = [string]::Format($d.Error, $script:sync.Error)
                    $script:lblStatus.Foreground = script:Get-Brush "#F23F43"
                } else {
                    $script:lblStatus.Text = $d.Done
                    $script:lblStatus.Foreground = script:Get-Brush "#23A55A"
                }

                script:Set-State $true
                try {
                    $script:ps.EndInvoke($script:h)
                    $script:ps.Dispose()
                    $script:rs.Close()
                    $script:rs.Dispose()
                } catch {}
            }
        })
        $script:timer.Start()
    }

    $btnInstall.Add_Click({ Run-Action "Install" })
    $btnUninstall.Add_Click({ Run-Action "Uninstall" })

    Update-Language
    Update-Theme

    $window.Add_Loaded({
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
        if ($hwnd -ne [System.IntPtr]::Zero) {
            [void][WinUtil.WinUtil]::SetForegroundWindow($hwnd)
        }
        [void]$window.Activate()
        [void]$window.Focus()
    })

    $window.WindowState = 'Normal'
    $window.Topmost = $true
    [void]$window.Activate()
    [void]$window.Focus()
    [void]$window.ShowDialog()
}

if ([System.Threading.Thread]::CurrentThread.GetApartmentState() -ne [System.Threading.ApartmentState]::STA) {
    $t = New-Object System.Threading.Thread([System.Threading.ThreadStart]{ Start-WpfInstallerApp })
    $t.SetApartmentState([System.Threading.ApartmentState]::STA)
    $t.Start()
    $t.Join()
} else {
    [void](Start-WpfInstallerApp)
}